-- 奇门遁甲 格子类
---@class QiMenDunJiaGridUnit @
---@field super SceneGridSix @SceneGridSix
SceneGridSix = require("Battle.Data.SceneGridSix")
local M = class("QiMenDunJiaGridUnit", SceneGridSix)

function M:init( gridId, placeGridData, w_pos, h_pos )
    M.super.init(self, w_pos, h_pos )
    self.m_gridId = gridId
    -- w3.15， h3.6
    local itemWidth = Battle.SceneGridConfig.qmdj_grid_width
    local itemHeight = Battle.SceneGridConfig.qmdj_grid_height
    local itemOffset = Battle.SceneGridConfig.qmdj_grid_offset
    self.w_pos = w_pos 
    self.h_pos = h_pos
    self.placeGridData = placeGridData
    local isDualLine = ((w_pos % 2) ~= 0)
    local offsetValue = isDualLine and (itemWidth / 2) or 0    
    self.m_posX = w_pos * itemOffset
    self.m_posY = 0
    self.m_posZ = h_pos * itemWidth + offsetValue
    --self.m_zs_id = placeGridData.zs_id          --- 地上物      --  地图生成的，本地的 树，草            ------------------------------ 暂不使用数据
    --- 地块是否可行（本地数据）
    self.m_sx_id = self.placeGridData.sx_id          
    
    --索引
    self.index_pos = {x = 0, y = 0 }
    self.index_pos.x = self.w_pos;
    self.index_pos.y = self.h_pos;
    self.vec2.x = self.m_posX
    self.vec2.y =  self.m_posZ
    self.position = Vector3( self.vec2.x, 0, self.vec2.y )
    
    -- 黑色地块的模板id
    self.m_blackModelTypeId = 111
    local gve_massifData = ConfigManager:getCfgByName("gve_massif")
    local gridModelXlsxData = gve_massifData[self.m_blackModelTypeId] or {}
    self.m_blackModelName = gridModelXlsxData.building_model
    
    -- 格子上有人(玩家实例id)
    self.m_existPlayerUid = -1
    
    -- 多格建筑索引绑定(子格用m_relationGridId， 母格用m_relationGridIdList)
    self.m_relationGridId = -1
    self.m_relationGridIdList = {}
    
    -- 怪物刷新--柱子相关数据(和策划对过，只配置一个关系，多的关系不处理)
    self.m_monsterRefreshGridId = -1
    -- 八卦阵标记
    self.m_wuzhuangSign = false
    
    self:reset()
end

function M:setWuzhuangSign(isWuzhuangSign)
    self.m_wuzhuangSign = isWuzhuangSign
end

function M:setMonsterRefreshGridId(gridId)
    self.m_monsterRefreshGridId = gridId
end

-- 设置关联建筑id  -- (子母格关联的子格集合)
function M:setRelationGridlist(m_relationGridIdList)
    self.m_relationGridIdList = m_relationGridIdList
end

-- 设置关联建筑id  -- (子母格关联的母格id)
function M:setRelationGridId(gridId)
    self.m_relationGridId = gridId
end

-- 刷新格子类型 及是否可行，障碍，怪物，宝箱，
function M:refreshGridData(serverData, isWalk)
    self:setGridType(serverData, isWalk)
    -- 是否可以移动(普通格子，出生点)
    local isWalkType = (self.m_gridType == GlobalConfig.GridType.Normal) or (self.m_gridType == GlobalConfig.GridType.BirthPoint) 
    self.IsVisi = isWalkType --and self.m_isWalk
end

function M:setGridType(serverData, isWalk)
    -- 是否走过
    self.m_isWalk = isWalk
    -- 功能类地上物id
    self.specialId = -1
    -- 地块状态：0：未操作，1：已完成
    self.gridStatus = 0
    local isEmptyGrid = (self.m_sx_id == -1) or (self.placeGridData.grid_id < 0)
    self.m_gridModelType = self.placeGridData.grid_id
    local m_groundConfigId = self.placeGridData.gn_id
    local gve_massifData = ConfigManager:getCfgByName("gve_massif")
    local gridModelXlsxData = gve_massifData[self.m_gridModelType] or {}
    self.m_gridModelName = gridModelXlsxData.building_model
    local groundConfigIdXlsxData = gve_massifData[m_groundConfigId] or {}
    self.hideFogConfig = -1
    if groundConfigIdXlsxData.fog_show and (groundConfigIdXlsxData.fog_show ~= "") then
        self.hideFogConfig = tonumber(groundConfigIdXlsxData.fog_show)
    end
    -- 黑色地块是否显示模型，走策划配置
    self.m_isShowModel = (groundConfigIdXlsxData.building_isshow == 1)
    self.m_gridType = isEmptyGrid and GlobalConfig.GridType.Empty or GlobalConfig.GridType.Normal
    -- (nums<=0)是因为打死怪物之后，服务器把怪物格子数据清空了，清空的也表示普通格子
    if not isEmptyGrid and (serverData ~= nil) and (table.nums(serverData) > 0) then
        self.specialId = serverData.massif_id
        self.m_gridType = serverData.type
        self.gridStatus = serverData.status
    end
end

function M:setExistPlayerUid(existPlayerUid)
    self.m_existPlayerUid = existPlayerUid
end

--重置
function M:reset()
    self.parent = nil;
    self.G = 0;
    self.H = 0;
    self.F = 0;
end

--disable
function M:disable(  )
    
end

return M